// Vendored verbatim from the Agentic Owners policy core; see README.md in
// this directory. Matching semantics must stay identical to the source's.

import { minimatch } from "minimatch";

export type PatternMatchOptions = {
  /**
   * When true, a `dir/` pattern whose directory is a glob claims the files
   * under every directory the glob matches, as gitignore does. A directory
   * that starts with `!` stays literal either way.
   */
  readonly globDirectoryPatterns?: boolean;
};

export const AO_GLOB_DIRECTORY_PATTERNS_ENV = "AO_GLOB_DIRECTORY_PATTERNS";

/**
 * The glob-directory switch from `AO_GLOB_DIRECTORY_PATTERNS`: `1`, `true` or
 * `yes` turns it on, and anything else, unset included, leaves it off. Turn it
 * on only after the Origin shadow counter
 * `origin.agentic_owners.glob_dir_shadow_mismatch` has run and its owner has
 * reviewed the repos, files and patterns it reports.
 */
export function globDirectoryPatternsFromEnv(
  env: Readonly<Record<string, string | undefined>> = process.env,
): PatternMatchOptions {
  const value = env[AO_GLOB_DIRECTORY_PATTERNS_ENV]?.trim().toLowerCase();
  return { globDirectoryPatterns: value === "1" || value === "true" || value === "yes" };
}

/**
 * CODEOWNERS-style path matching. While the glob-directory switch is off, a
 * `dir/` pattern is read literally, a glob included: `src/d?cs/` claims only
 * files under a directory named `src/d?cs`. With it on, the glob matches
 * directories as in gitignore. Complex prefixes before a terminal `/**`
 * deliberately fall through to minimatch below.
 */
export function patternMatchesFile(
  pattern: string,
  filepath: string,
  options: PatternMatchOptions = globDirectoryPatternsFromEnv(),
): boolean {
  const patternIsRooted = pattern.startsWith("/");
  const normalizedPattern = pattern.replace(/^\/+/, "");
  const normalizedPath = filepath.replace(/^\/+/, "");

  if (normalizedPattern === "**" || normalizedPattern === "*") {
    return true;
  }

  const literalPrefix = normalizedPattern.replace(/\*+$/, "");
  if (normalizedPattern.endsWith("**") && !hasComplexGlob(literalPrefix)) {
    const prefix = literalPrefix.replace(/\\(.)/g, "$1").replace(/\/+$/, "");
    if (prefix !== "" && normalizedPath.startsWith(`${prefix}/`)) {
      return true;
    }
    if (literalPrefix === "" || literalPrefix.endsWith("/")) {
      return false;
    }
    if (normalizedPath === prefix) {
      return true;
    }
    if (patternIsRooted && !literalPrefix.includes("/") && normalizedPath.includes("/")) {
      return false;
    }
    // gitignore reads `x**` as `x*`.
    return globMatches(normalizedPath, `${literalPrefix}*`);
  }

  const globDirectory =
    options.globDirectoryPatterns === true ? globDirectoryOf(normalizedPattern) : undefined;
  if (globDirectory !== undefined) {
    const rootLevelOnly = patternIsRooted && !globDirectory.includes("/");
    return ancestorDirectories(normalizedPath).some(
      (ancestor) =>
        !(rootLevelOnly && ancestor.includes("/")) && globMatches(ancestor, globDirectory),
    );
  }

  if (normalizedPattern.endsWith("/")) {
    const prefix = normalizedPattern.replace(/\\(.)/g, "$1").replace(/\/+$/, "");
    if (!patternIsRooted && !prefix.includes("/")) {
      return normalizedPath.startsWith(`${prefix}/`) || normalizedPath.includes(`/${prefix}/`);
    }
    return prefix !== "" && normalizedPath.startsWith(`${prefix}/`);
  }

  if (globstarDirectoryPatternMatches(normalizedPattern, normalizedPath)) {
    return true;
  }

  return globMatches(normalizedPath, normalizedPattern);
}

function globMatches(filepath: string, pattern: string): boolean {
  try {
    return minimatch(filepath, pattern, {
      dot: true,
      matchBase: !pattern.includes("/"),
      nocase: false,
    });
  } catch {
    return false;
  }
}

function hasComplexGlob(pattern: string): boolean {
  return /[*?[\]{}!()+@]/.test(pattern);
}

function globDirectoryOf(normalizedPattern: string): string | undefined {
  if (!normalizedPattern.endsWith("/")) {
    return undefined;
  }
  const directory = normalizedPattern.replace(/\/+$/, "");
  return hasComplexGlob(directory) && !directory.startsWith("!") ? directory : undefined;
}

function ancestorDirectories(filepath: string): string[] {
  const segments = filepath.split("/").slice(0, -1);
  return segments.map((_, index) => segments.slice(0, index + 1).join("/"));
}

/** Higher score means a more specific pattern (used to break ties within one policy.yml). */
export function patternSpecificity(pattern: string): number {
  const normalized = pattern.replace(/^\/+/, "");
  const globIndex = normalized.search(/[*?[\]{}!]/);
  const literalPrefix = globIndex === -1 ? normalized : normalized.slice(0, globIndex);
  const segments = literalPrefix.split("/").filter((segment) => segment !== "").length;
  return literalPrefix.length * 100 + segments;
}

function globstarDirectoryPatternMatches(pattern: string, filepath: string): boolean {
  if (!pattern.startsWith("**/")) {
    return false;
  }
  const suffix = pattern.slice("**/".length);
  if (suffix === "" || hasComplexGlob(suffix)) {
    return false;
  }
  return (
    filepath === suffix ||
    filepath.endsWith(`/${suffix}`) ||
    filepath.startsWith(`${suffix}/`) ||
    filepath.includes(`/${suffix}/`)
  );
}
